using System;using System.Linq;using System.Collections.Generic;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class MechanismCopies {public static MechanismPart CloneShape(this MechanismPart p){return CADDocument.Serializer().Deserialize<MechanismPart>(CADDocument.Serializer().Serialize(p));}}
 public sealed class RobotJointLoad {public string Id,Unit,Message;public double SignedEffort,Required,Available,MotorRequired,MotorRpm,Margin;public bool Enough,SpeedKnown;}
 public sealed class RobotAnalysis {public List<RobotJointLoad> Joints=new List<RobotJointLoad>();public List<string> Errors=new List<string>(),Notes=new List<string>();public double TotalMass;public int SampledPoses,PotentialCollisions;public bool Valid{get{return Errors.Count==0;}}}
 public static class RobotSolver {
  public static Point3D LoadPoint(RobotDocument doc,RobotJoint joint,Dictionary<string,RobotPose> poses){var pose=poses[joint.Id];double extension=RobotToolGeometry.LoadExtension(doc,joint);if(extension==0)return pose.Tip;var direction=new Vector3D(joint.EndX,joint.EndY,joint.EndZ);direction.Normalize();return pose.Tip+pose.Output.Transform(direction)*extension;}

  static Matrix3D Pose(RobotCadEntry e,Dictionary<string,RobotPose> fk){var p=fk[e.JointId];var local=e.Local;if(e.NativeMotion!=null)local=e.NativeBasePlacement*e.NativeMotion.At(p.Value*Math.PI/180*e.NativeRatio,0)*local;return local*(e.InputSide?p.Base:p.Output);}
  public static RobotAnalysis Solve(RobotBuild build,Dictionary<string,RobotPose> poses=null){var r=new RobotAnalysis();r.Errors.AddRange(build.Model.Errors);if(r.Errors.Count>0)return r;var d=build.Document;var fk=poses??build.Current;r.TotalMass=build.Entries.Values.Sum(e=>build.Mass(e))+d.Joints.Sum(j=>j.Payload);foreach(var j in d.Ordered()){double signed=0;var pose=fk[j.Id];foreach(var e in build.Entries.Values.Where(e=>e.OwnerId!=null&&!e.Guide&&d.Descendant(e.OwnerId,j.Id))){double mass=build.Mass(e);var centre=Pose(e,fk).Transform(RobotBuild.Centre(e.Part));var force=new Vector3D(0,0,-mass*d.Gravity);signed+=j.Linear?Vector3D.DotProduct(force,pose.Axis):Vector3D.DotProduct(Vector3D.CrossProduct((centre-pose.Origin)/1000,force),pose.Axis);}foreach(var tool in d.Joints.Where(t=>d.Descendant(t.Id,j.Id))){var force=new Vector3D(tool.ForceX,tool.ForceY,tool.ForceZ-tool.Payload*d.Gravity);signed+=j.Linear?Vector3D.DotProduct(force,pose.Axis):Vector3D.DotProduct(Vector3D.CrossProduct((LoadPoint(d,tool,fk)-pose.Origin)/1000,force),pose.Axis);}double ratio=j.Reduction,efficiency=j.Efficiency;if(j.CustomTransmission!=null){var s=MechanismSolver.Solve(j.CustomTransmission);var output=s.Shafts[j.TransmissionOutput];ratio=1/Math.Abs(output.SpeedRatio);efficiency=output.PathEfficiency;}double available=j.MotorTorque*ratio*efficiency;if(j.Linear)available*=2*Math.PI/(j.ScrewLead/1000);double required=Math.Abs(signed)*d.SafetyFactor,motor=required/(ratio*efficiency)*(j.Linear?j.ScrewLead/1000/(2*Math.PI):1),rpm=j.Linear?j.Speed/j.ScrewLead*60*ratio:j.Speed/6*ratio;bool known=rpm<=j.MotorMaxRpm+1e-7;var load=new RobotJointLoad{Id=j.Id,Unit=j.Linear?"Н":"Н·м",SignedEffort=signed,Required=required,Available=available,MotorRequired=motor,MotorRpm=rpm,Margin=available-required,Enough=required<=available+1e-9&&known,SpeedKnown=known,Message=j.Mode==RobotJointMode.Неподвижный?"Неподвижное соединение":!known?"Нет данных момента при этой скорости":required>available?"Момента / усилия недостаточно":"Проходит статическую оценку"};if(j.Mode==RobotJointMode.Неподвижный){load.Enough=true;load.Available=0;load.MotorRpm=0;load.MotorRequired=0;}r.Joints.Add(load);}
   r.Notes.AddRange(build.Notes);r.Notes.Add("Момент рассчитан от собственного веса геометрии, заданной массы моторов, полезной нагрузки и внешних сил с коэффициентом запаса "+Engine.F(d.SafetyFactor)+". Моторный шаблон условный: введите паспортный момент на рабочих оборотах.");r.Notes.Add("Это статическая оценка в выбранной позе. Разгон, торможение, упругость, усталость, точность, прочность крепежа и нагрев не рассчитаны. Анимация подтверждает кинематические связи, но не работоспособность изготовленного робота.");return r;}
  public static RobotAnalysis CheckRange(RobotBuild b,int samples){samples=Math.Max(8,Math.Min(128,samples));var result=Solve(b);if(!result.Valid)return result;var d=b.Document;var random=new Random(17);for(int i=0;i<samples;i++){var values=new Dictionary<string,double>();foreach(var j in d.Joints){double value=i==0?j.Position:i==1?Math.Max(j.Minimum,Math.Min(j.Maximum,0)):i==2?j.Minimum:i==3?j.Maximum:j.Minimum+(j.Maximum-j.Minimum)*random.NextDouble();values[j.Id]=value;}var fk=RobotKinematics.Evaluate(d,0,false,values);var next=Solve(b,fk);for(int n=0;n<result.Joints.Count;n++){if(next.Joints[n].Required>result.Joints[n].Required){result.Joints[n].Required=next.Joints[n].Required;result.Joints[n].SignedEffort=next.Joints[n].SignedEffort;result.Joints[n].MotorRequired=next.Joints[n].MotorRequired;result.Joints[n].Margin=next.Joints[n].Margin;result.Joints[n].Enough=next.Joints[n].Enough;}}result.PotentialCollisions+=PossibleCollisions(d,fk);}result.SampledPoses=samples;result.Notes.Add("Проверено "+samples+" выборочных поз; показана наибольшая найденная нагрузка. Это не исчерпывающий поиск максимума и не проверка геометрии всех движущихся поверхностей.");result.Notes.Add("Грубых сближений несоседних звеньев / габаритов приводов: "+result.PotentialCollisions+". Каждое требует детальной проверки; отсутствие таких сближений не подтверждает отсутствие всех столкновений.");return result;}
  static int PossibleCollisions(RobotDocument d,Dictionary<string,RobotPose> fk){int found=0;for(int i=0;i<d.Joints.Count;i++)for(int k=i+1;k<d.Joints.Count;k++){var a=d.Joints[i];var b=d.Joints[k];if(a.ParentId==b.Id||b.ParentId==a.Id)continue;var x=fk[a.Id];var y=fk[b.Id];if((x.Origin-y.Origin).Length<(a.GearboxDiameter+b.GearboxDiameter)/2)found++;if(SegmentDistance(x.Origin,x.Tip,y.Origin,y.Tip)<(a.BeamWidth+b.BeamWidth)/2)found++;}return found;}
  static double SegmentDistance(Point3D p1,Point3D q1,Point3D p2,Point3D q2){var u=q1-p1;var v=q2-p2;var w=p1-p2;double a=Vector3D.DotProduct(u,u),b=Vector3D.DotProduct(u,v),c=Vector3D.DotProduct(v,v),d=Vector3D.DotProduct(u,w),e=Vector3D.DotProduct(v,w),den=a*c-b*b,s=den>1e-12?Math.Max(0,Math.Min(1,(b*e-c*d)/den)):0,t=Math.Max(0,Math.Min(1,(b*s+e)/Math.Max(c,1e-12)));s=Math.Max(0,Math.Min(1,(b*t-d)/Math.Max(a,1e-12)));return (w+u*s-v*t).Length;}
 }
}

